const API_URL="../api/share";async function compressText(e){const t=new Blob([e],{type:"text/plain"}).stream().pipeThrough(new CompressionStream("gzip")),n=new Response(t),o=await n.arrayBuffer(),r=new Uint8Array(o);let a="";for(let e=0;e<r.byteLength;e++)a+=String.fromCharCode(r[e]);return btoa(a).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"")}async function decompressText(e){let t=e.replace(/-/g,"+").replace(/_/g,"/");for(;t.length%4;)t+="=";const n=atob(t),o=new Uint8Array(n.length);for(let e=0;e<n.length;e++)o[e]=n.charCodeAt(e);const r=new Blob([o]).stream().pipeThrough(new DecompressionStream("gzip")),a=new Response(r);return await a.text()}function generateCode(){return Math.floor(1e5+9e5*Math.random()).toString()}async function deriveKey(e,t){const n=new TextEncoder,o=await crypto.subtle.importKey("raw",n.encode(e),"PBKDF2",!1,["deriveKey"]);return crypto.subtle.deriveKey({name:"PBKDF2",salt:t,iterations:1e3,hash:"SHA-256"},o,{name:"AES-GCM",length:256},!1,["encrypt","decrypt"])}async function encryptPayload(e,t){const n=new TextEncoder,o=crypto.getRandomValues(new Uint8Array(16)),r=crypto.getRandomValues(new Uint8Array(12)),a=await deriveKey(t,o),l=await crypto.subtle.encrypt({name:"AES-GCM",iv:r},a,n.encode(e)),i=new Uint8Array(o.length+r.length+l.byteLength);i.set(o,0),i.set(r,o.length),i.set(new Uint8Array(l),o.length+r.length);let d="";for(let e=0;e<i.byteLength;e++)d+=String.fromCharCode(i[e]);return btoa(d).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"")}async function decryptPayload(e,t){let n=e.replace(/-/g,"+").replace(/_/g,"/");for(;n.length%4;)n+="=";const o=atob(n),r=new Uint8Array(o.length);for(let e=0;e<o.length;e++)r[e]=o.charCodeAt(e);const a=r.slice(0,16),l=r.slice(16,28),i=r.slice(28),d=await deriveKey(t,a),c=await crypto.subtle.decrypt({name:"AES-GCM",iv:l},d,i);return(new TextDecoder).decode(c)}async function generateShare(){const e=document.getElementById("plainInput").value;if(!e.trim())return;const t=document.getElementById("btnGenerate");t.disabled=!0,t.textContent="Generating...";try{const t=await compressText(e),n=window.location.origin+window.location.pathname;document.getElementById("offlineLink").value=n+"#data="+t;let o=generateCode();const r=await encryptPayload(e,o),a=await fetch(API_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({code:o,value:r})});if(!a.ok)throw new Error("Database sharing failed.");const l=await a.json();if(l.error)throw new Error(l.error);const i=o.substring(0,3)+" "+o.substring(3);document.getElementById("shareCode").value=i,document.getElementById("shareLink").value=n+"#code="+o,document.getElementById("outputBlock").style.display="block",clearError()}catch(e){showError("Sharing failed: "+e.message+". Offline fallback link is still available below."),document.getElementById("outputBlock").style.display="block"}finally{t.disabled=!1,t.textContent="Generate Share"}}async function retrieveShare(){let e=document.getElementById("retrieveInput").value.trim();if(!e)return;const t=document.getElementById("btnRetrieve");t.disabled=!0,t.textContent="Retrieving...";try{let t="";if(e.includes("#data=")){const n=e.split("#data=")[1];t=await decompressText(n)}else{let n=e.replace(/[\s-]/g,"");if(n.includes("#code=")&&(n=n.split("#code=")[1]),n.length<6)throw new Error("Code must be 6 digits (e.g. 752 936)");const o=n.substring(0,6),r=o,a=await fetch(`${API_URL}?code=${o}`);if(!a.ok)throw new Error("Code not found or expired.");const l=await a.json();if(l.error||!l.result)throw new Error("Code not found or expired.");const i=l.result;t=await decryptPayload(i,r)}document.getElementById("retrievedOutput").value=t,document.getElementById("retrieveOutputBlock").style.display="block",clearError()}catch(e){showError("Failed to retrieve: "+e.message)}finally{t.disabled=!1,t.textContent="Retrieve Text"}}function copyValue(e,t){const n=document.getElementById(t);navigator.clipboard.writeText(n.value),flashCopied(e)}function clearPlainInput(){document.getElementById("plainInput").value="",document.getElementById("outputBlock").style.display="none",clearError()}function clearRetrieveInput(){document.getElementById("retrieveInput").value="",document.getElementById("retrieveOutputBlock").style.display="none",clearError()}function showError(e){const t=document.getElementById("shareError");t.textContent=e,t.style.display="block"}function clearError(){document.getElementById("shareError").style.display="none"}function copyAutoLoaded(e){const t=document.getElementById("autoLoadedOutput").value;navigator.clipboard.writeText(t),flashCopied(e)}function dismissAutoLoaded(){document.getElementById("autoLoadedPanel").style.display="none",window.location.hash=""}window.addEventListener("DOMContentLoaded",async()=>{const e=window.location.hash;if(e.startsWith("#code="))try{const t=e.slice(6),n=t.replace(/[\s-]/g,"").substring(0,6),o=n,r=await fetch(`${API_URL}?code=${n}`);if(r.ok){const e=await r.json();if(e.result){const t=await decryptPayload(e.result,o);document.getElementById("autoLoadedOutput").value=t,document.getElementById("autoLoadedPanel").style.display="block"}else showError("The shared link has expired or is invalid.")}else showError("The shared link has expired or is invalid.")}catch(e){showError("Failed to retrieve or decrypt shared text.")}else if(e.startsWith("#data="))try{const t=e.slice(6),n=await decompressText(t);document.getElementById("autoLoadedOutput").value=n,document.getElementById("autoLoadedPanel").style.display="block"}catch(e){showError("Failed to decompress shared link.")}});